import {diamondGraph,grapheneGraph,c60Graph} from './carbon-models.js?v=20261023-physicscomplete01';
import {renderModel,renderDiagram,enable3D} from './visual.js?v=20261023-physicscomplete01';
const text=(x,y,s,size=12,colour='#f8f6f2')=>`<text x="${x}" y="${y}" fill="${colour}" text-anchor="middle" font-family="sans-serif" font-size="${size}">${s}</text>`;
const svg=(body,aria)=>`<svg class="lab-svg" viewBox="0 0 440 285" role="img" aria-label="${aria}">${body}</svg>`;
export function carbonDiagram(kind,slide=0){
 if(kind==='diamond')return svg('<path d="M220 135L140 75M220 135L300 75M220 135L160 215M220 135L285 205" stroke="#b7c8d6" stroke-width="3"/>'+[[220,135],[140,75],[300,75],[160,215],[285,205]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="${i?14:20}" fill="${i?'#b7c8d6':'#ed8b78'}"/>`+text(x,y+4,'C',12,'#182e44')).join('')+text(220,265,'Four neighbours · tetrahedral fragment, projected into 2D',10),'Central diamond carbon with four covalent neighbours; the network continues beyond them');
 if(kind==='graphite'||kind==='graphene'){let art='';const g=grapheneGraph(),layers=kind==='graphite'?3:1;for(let r=0;r<layers;r++){const dy=layers===3?r*75+45:130,dx=r===1?slide*.3:0;const xy=g.atoms.map(p=>[220+p[0]*38+dx,dy+p[1]*(layers===3?9:30)]);art+=g.bonds.map(([a,b])=>`<path d="M${xy[a].join(' ')}L${xy[b].join(' ')}" stroke="#b7c8d6" stroke-width="2"/>`).join('');art+=xy.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3" fill="#f0b4a6"/>`).join('');}art+=text(220,275,kind==='graphite'?'Projected sheets · no covalent bonds between layers':'One sheet · the network continues beyond its edges',10);return svg(art,kind==='graphite'?'Three projected hexagonal sheets without interlayer covalent bonds':'Single hexagonal graphene network fragment');}
 if(kind==='fullerene')return svg('<circle cx="220" cy="130" r="100" fill="none" stroke="#d4dfe7" stroke-width="2"/><polygon points="220,65 270,101 251,160 189,160 170,101" fill="none" stroke="#f0b4a6" stroke-width="3"/><path d="M220 65V30M270 101L315 85M251 160L278 210M189 160L162 210M170 101L125 85" stroke="#b7c8d6" stroke-width="2"/>'+text(220,270,'C₆₀ cage · pentagon highlighted · schematic projection',10),'Schematic spherical fullerene cage with a pentagonal ring, not a full atom-count diagram');
 return svg('<ellipse cx="115" cy="135" rx="25" ry="50" fill="none" stroke="#f0b4a6"/><ellipse cx="330" cy="135" rx="25" ry="50" fill="none" stroke="#f0b4a6"/><path d="M115 85H330M115 185H330" stroke="#b7c8d6" stroke-width="3"/>'+text(220,245,'Long hollow cylinder · shape sketch, not atomic bonds',11),'Hollow cylindrical nanotube shape sketch');
}
export function showCarbon(kind,slide=0){
 if(kind==='nanotube'){renderDiagram('A carbon nanotube','Cylindrical fullerene',carbonDiagram(kind),'SHAPE SKETCH · NOT ATOMIC TOPOLOGY');return;}
 let graph,atoms,bonds,name,formula,zoom;
 if(kind==='diamond'){graph=diamondGraph();atoms=graph.atoms.map((p,i)=>[i===graph.focus?'Focus':'K',...p]);bonds=graph.bonds;name='Diamond network fragment';formula='Central gold atom · four neighbours';zoom=16;}
 else if(kind==='fullerene'){graph=c60Graph();atoms=graph.atoms.map(p=>['K',...p]);bonds=graph.bonds;name='Buckminsterfullerene';formula='C₆₀ · 60 atoms';zoom=11;}
 else{graph=grapheneGraph();atoms=[];bonds=[];const layers=kind==='graphite'?3:1;for(let r=0;r<layers;r++){const offset=atoms.length;for(const p of graph.atoms){const x=p[0]*.6+(r===1?slide*.006:0),y=p[1]*.6,z=(r-(layers-1)/2)*.95;atoms.push(['K',x,y*.65-z*.65,y*.65+z*.65]);}bonds.push(...graph.bonds.map(e=>e.map(i=>i+offset)));}name=kind==='graphite'?'Graphite layer fragments':'One graphene sheet';formula=kind==='graphite'?'Three sheets · no interlayer covalent bonds':'One atom thick · giant sheet';zoom=15;}
 enable3D();renderModel({name,formula,aria:name+'. All spheres represent carbon atoms. '+formula+'. Drag or use arrow keys to rotate; plus and minus zoom.',kicker:'SCHEMATIC CARBON MODEL · ARTIFICIAL EDGES / SIZES',zoom,atoms,bonds,bondRadius:.035,diagram:carbonDiagram(kind,slide)});
}
